// Кейс: .qa/tests/monitoring/MON-023.md · план: .qa/e2e-app/specs/app.md (1.24)
// ПОЛУАВТОМАТ (@manual-assist, @data): запускает мониторинг (сеанс в «היסטוריה»), человек сдвигает телефон →
// «המכשיר זז» → «כיוון מחדש» → на «כוונו את המצלמה מחדש» превью от края до края (просьба клиента #e946f4) →
// галочка → «חזרה לניטור» → «תקין» → «כבה את המצלמה». Ложные тревоги «זוהתה סכנה בבריכה» — #18bb68, НЕ провал, только лог.
// Только с BANCI_MONITORING=1 И BANCI_MANUAL_ASSIST=1 (в обычном регрессе — пропуск).
import { by, assert, skip, checkedFromValue } from '../../lib/appium.mjs';
import { waitEnabled, assertPreviewFullWidth } from '../../lib/banci.mjs';
import {
  requireMonitoringOptIn, startMonitoring, endMonitoring, MOVED, logDangerAlarm, dangerClosed, dismissFalseDanger,
} from '../../lib/monitoring.mjs';

export const name = '«כוונו את המצלמה מחדש»: превью камеры на всю ширину экрана #e946f4 @iphone @app @data @manual-assist';

const pause = (ms) => new Promise((r) => setTimeout(r, ms)); // интервал опроса, не ожидание результата

export default async function (app) {
  requireMonitoringOptIn();
  if (process.env.BANCI_MANUAL_ASSIST !== '1') skip('полуавтомат: сдвиг телефона делает человек — запуск только с BANCI_MANUAL_ASSIST=1 (и BANCI_MONITORING=1)');
  const waitSec = Number(process.env.BANCI_MOVE_WAIT_SEC || 180);
  const alarms = [];
  await startMonitoring(app);

  console.log(`\n     СДВИГ: поверните телефон ~90° (до ${waitSec} с), потом положите и не трогайте`);
  const end = Date.now() + waitSec * 1000;
  while (!(await app.exists(by.exact(MOVED)))) {
    assert(Date.now() < end, `сдвиг телефона → «${MOVED}» за ${waitSec} с (ПРЕДУСЛОВИЕ: телефон сдвинут человеком)`);
    if (!(await logDangerAlarm(app, alarms, 'e946f4-move'))) dangerClosed(alarms);
    await pause(600);
  }

  await app.tap(by.exact('כיוון מחדש', 'Button'), { what: '«כיוון מחדש» в окне сбоя' });
  await app.waitFor(by.contains('כוונו את המצלמה'), { timeout: 15000, what: 'экран «כוונו את המצלמה מחדש»' });
  await assertPreviewFullWidth(app, '«כוונו את המצלמה מחדש»');
  console.log(`     превью на «כוונו את המצלמה מחדש» → ${await app.screenshot('e946f4-recal-full-width').catch(() => '—')}`);

  const cb = await app.scrollTo(by.begins('כל שטח המים נראה'), { max: 4, what: 'галочка «כל שטח המים נראה בתמונה»' });
  if (checkedFromValue(await cb.attr('value')) !== true) await cb.click();
  const back = await app.waitFor(by.exact('חזרה לניטור', 'Button'), { what: '«חזרה לניטור»' });
  await waitEnabled(back, true, { timeout: 20000, what: '«חזרה לניטור» (кадр освещён, линза открыта)' });
  await back.click();
  await app.waitFor(by.exact('תקין'), { timeout: 20000, what: 'статус «תקין» после «חזרה לניטור»' });

  if (alarms.length) console.log(`     [#18bb68, не провал] ложных тревог опасности: ${alarms.length}`);
  await dismissFalseDanger(app);
  await endMonitoring(app);
}
